<?php

declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('ADMIN');
$q = trim((string)($_GET['q'] ?? ''));
$itemId = (int)($_GET['item_id'] ?? 0);
$type = strtoupper(trim((string)($_GET['type'] ?? 'ALL')));
if (!in_array($type, ['ALL', 'STOCK_IN', 'STOCK_OUT', 'ADJUSTMENT', 'WASTE'], true)) $type = 'ALL';
$transactions = admin_inventory_transactions(['q' => $q, 'item_id' => $itemId, 'type' => $type], 300);
$items = admin_inventory_items(['status' => 'ACTIVE']);
$pageTitle = 'Inventory Transactions'; $bodyClass = 'portal-page'; require __DIR__ . '/../includes/header.php';
?>
<div class="portal-shell"><?php require __DIR__ . '/../includes/sidebar.php'; ?><main class="portal-main inventory-main">
<header class="portal-page-header"><div><span class="eyebrow">INVENTORY</span><h1 class="mt-2 mb-1">Transaction history</h1><p class="text-muted mb-0">Audit stock receipts, usage, waste, and physical-count adjustments.</p></div><a class="btn btn-outline-coffee" href="<?= url('admin/inventory.php') ?>"><i class="bi bi-arrow-left me-2"></i>Inventory</a></header>
<section class="portal-card inventory-filter-card"><form method="get" class="inventory-history-filters"><div><label class="form-label" for="txSearch">Search</label><input class="form-control" id="txSearch" name="q" value="<?= e($q) ?>" placeholder="Item, code, or note"></div><div><label class="form-label" for="txItem">Item</label><select class="form-select" id="txItem" name="item_id"><option value="0">All items</option><?php foreach ($items as $item): ?><option value="<?= (int)$item['id'] ?>" <?= $itemId === (int)$item['id'] ? 'selected' : '' ?>><?= e((string)$item['item_code']) ?> · <?= e((string)$item['item_name']) ?></option><?php endforeach; ?></select></div><div><label class="form-label" for="txTypeFilter">Type</label><select class="form-select" id="txTypeFilter" name="type"><option value="ALL">All types</option><?php foreach (['STOCK_IN' => 'Stock In','STOCK_OUT' => 'Stock Out','WASTE' => 'Waste','ADJUSTMENT' => 'Adjustment'] as $value => $label): ?><option value="<?= $value ?>" <?= $type === $value ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></div><div class="inventory-filter-actions"><button class="btn btn-coffee" type="submit">Apply</button><a class="btn btn-outline-secondary" href="<?= url('admin/inventory-transactions.php') ?>">Reset</a></div></form></section>
<section class="portal-card mt-4"><div class="panel-heading"><div><span class="eyebrow">AUDIT LOG</span><h2><?= count($transactions) ?> transaction<?= count($transactions) === 1 ? '' : 's' ?></h2></div><span class="text-muted small">Latest 300 records</span></div>
<?php if (!$transactions): ?><div class="empty-state compact"><i class="bi bi-clock-history"></i><h3>No transactions found</h3><p>Stock movement will appear here once inventory is received or used.</p></div><?php else: ?><div class="table-responsive"><table class="table align-middle inventory-table mb-0"><thead><tr><th>Date</th><th>Item</th><th>Type</th><th>Movement</th><th>Balance after</th><th>Cost</th><th>Recorded by</th><th>Notes</th></tr></thead><tbody><?php foreach ($transactions as $tx): ?><tr><td><strong><?= e(date('M j, Y', strtotime((string)$tx['created_at']))) ?></strong><small class="d-block text-muted"><?= e(date('g:i A', strtotime((string)$tx['created_at']))) ?></small></td><td><a class="order-number-link" href="<?= url('admin/inventory-form.php?id=' . (int)$tx['inventory_item_id']) ?>"><?= e((string)$tx['item_name']) ?></a><small><?= e((string)$tx['item_code']) ?></small></td><td><span class="inventory-tx-badge <?= strtolower((string)$tx['type']) ?>"><?= e(str_replace('_', ' ', (string)$tx['type'])) ?></span></td><td class="fw-semibold"><?= e(inventory_decimal((float)$tx['quantity'])) ?> <?= e((string)$tx['unit']) ?></td><td><?= e(inventory_decimal((float)$tx['balance_after'])) ?> <?= e((string)$tx['unit']) ?></td><td><?= $tx['unit_cost'] !== null ? money((float)$tx['unit_cost']) : '—' ?></td><td><?= e(trim((string)($tx['first_name'] . ' ' . $tx['last_name'])) ?: 'System') ?></td><td class="text-muted small"><?= e((string)($tx['notes'] ?: '—')) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section></main></div><?php require __DIR__ . '/../includes/footer.php'; ?>
